import{z as o,x as d,o as l,c as A,q as r,j as B,D as n,d as E,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"中位数的中位数","description":"","frontmatter":{"title":"中位数的中位数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/median-of-medians.md","filePath":"cs/median-of-medians.md","lastUpdated":1791413859000}'),p={name:"cs/median-of-medians.md"};function m(D,a,c,h,T,u){const t=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=r('<h1 id="中位数的中位数" tabindex="-1">中位数的中位数 <a class="header-anchor" href="#中位数的中位数" aria-label="Permalink to &quot;中位数的中位数&quot;">​</a></h1><div class="epigraph"><p>每五元组取中位数，再取这些中位数的中位数当轴；两侧都丢掉常数比例，选择最坏 $\\Theta(n)$。</p><footer>—— 据 Blum, Floyd, Pratt, Rivest and Tarjan, Time Bounds for Selection, 1973；CLRS 第 9 章整理</footer></div><p>上一课<a href="/cs/select-kth">选择第 k 小</a>给出随机分区的期望线性，并点名 BFPRT「最坏线性存在、常数大」。本课不重写单侧递归。缺口是把保证轴写完：为何五、为何丢掉至少大约三成，以及递推 \\(T(n)\\le T(\\lceil n/5\\rceil)+T(7n/10+O(1))+O(n)\\) 为何仍 \\(\\Theta(n)\\)。后课图遍历不再问第 \\(k\\) 小。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机选择最坏平方：对手每次送最偏的轴。要最坏线性，轴的秩必须落在 \\([\\alpha n,(1-\\alpha)n]\\) 一类区间，使丢掉的一侧至少 \\(\\alpha n\\)。确定性构造：把 \\(n\\) 个键分成 \\(\\lceil n/5\\rceil\\) 组，每组五人取中位数；这 \\(\\lceil n/5\\rceil\\) 个中位数再递归选它们的中位数 \\(x\\)。\\(x\\) 至少大于（约）一半五元组里的三个键——「一半的一半的三」，约 \\(3n/10\\) 个键严格在 \\(x\\) 一侧，故另一侧至多约 \\(7n/10\\)。单侧递归规模 \\(\\le 7n/10\\)，外加找各组中位数的 \\(O(n)\\) 与对中位数数组的 \\(T(n/5)\\)。</p><p><span class="marginnote">数字实例：\\(n=100\\) 时分 20 组，每组取第 3 小，凑出 20 个组中位数，再取它们的中位数 \\(x\\)。至少 10 个组中位数 \\(\\ge x\\)，每组贡献 3 个键，\\(x\\) 的一侧就至少压着约 30 个键——「一半的一半的三」由此得名。</span></p><p>缺口是这条比例，不是再发明分区。三元组或七元组也能证，五是教科书常数折中。</p><h3 id="保证轴不是默认实现" tabindex="-1">保证轴不是默认实现 <a class="header-anchor" href="#保证轴不是默认实现" aria-label="Permalink to &quot;保证轴不是默认实现&quot;">​</a></h3><p>每层对全部键做分组与两次选择，常数远大于随机分区。主干实现仍是上一课的随机。本课证明比较模型里选择的最坏上界与 \\(\\Omega(n)\\) 下界同阶。</p><p><span class="marginnote">Blum et al. 1973（BFPRT）。CLRS 9.3 用五元组画「大于 \\(x\\) / 小于 \\(x\\)」的格子。主定理不能直接套两个不同 \\(b\\)，用替换法：猜 \\(T(n)\\le cn\\) 后留出 \\(c\\) 吸收 \\(n/5+7n/10\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>Select(A,k)</code>：不足常数直接排。否则五五分组，各组中位数形成数组 \\(M\\)，递归 <code>Select(M, |M|/2)</code> 得 \\(x\\)。以 \\(x\\) 为轴分区，得秩 \\(q\\)；与上一课一样只走一侧。正确性：分区仍对；\\(x\\) 的秩保证两侧都 \\(\\Omega(n)\\)。</p><p><span class="marginnote">术语翻译：替换法是「先猜答案再验货」——猜 \\(T(n)\\le cn\\)，代入递推右边，\\(n/5\\) 与 \\(7n/10\\) 的系数和是 \\(9/10\\lt 1\\)，多出的部分能被同一个 \\(c\\) 吸收，猜想自洽成立；系数和一旦 \\(\\gt 1\\)，这个猜法就失效。</span></p>',13)),(l(),B(s,null,{default:n(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22n%20%E4%B8%AA%E9%94%AE%22%5D%20--%3E%20G5%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%0A%20%20G5%20--%3E%20MOM%5B%22%E4%B8%AD%E4%BD%8D%E6%95%B0%E7%9A%84%E4%B8%AD%E4%BD%8D%E6%95%B0%20x%22%5D%0A%20%20MOM%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%20--%3E%20ONE%5B%22%E5%8D%95%E4%BE%A7%E9%80%92%E5%BD%92%20%E2%89%A4%207n%2F10%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/akra-bazzi"},"Akra–Bazzi"),E(" 也能读 \\(T(n/5)+T(7n/10)+O(n)\\)：解 \\((1/5)^p+(7/10)^p=1\\) 得 \\(p\\approx0.84\\lt1\\)，积分给出 \\(\\Theta(n)\\)。课内用替换法即可。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"格子论证要小心地板：大约 \\(3n/10\\) 是渐近，小 \\(n\\) 直接排序切开。不要把「中位数」当成均值：五元组中位数是比较出来的第 3 小。也不要把本课当排序：排完五元组只为造轴，全表仍无序。",-1)),a[6]||(a[6]=e("p",null,"\\(x\\) 为什么两侧都至少丢掉约 \\(3n/10\\)，格子账可以逐项摆开：",-1)),(l(),B(s,null,{default:n(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BD%B4%20x%EF%BC%9A%E4%B8%AD%E4%BD%8D%E6%95%B0%E7%9A%84%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%20--%3E%20BIG%5B%22%E7%BA%A6%E4%B8%80%E5%8D%8A%E7%BB%84%EF%BC%9A%E7%BB%84%E4%B8%AD%E4%BD%8D%E6%95%B0%20%E2%89%A5%20x%22%5D%0A%20%20BIG%20--%3E%20G3%5B%22%E8%BF%99%E4%BA%9B%E7%BB%84%E5%90%84%E6%9C%89%203%20%E4%B8%AA%E9%94%AE%20%E2%89%A5%20x%22%5D%0A%20%20G3%20--%3E%20DISC%5B%22x%20%E4%B8%80%E4%BE%A7%E8%87%B3%E5%B0%91%E7%BA%A6%203n%2F10%20%E4%B8%AA%E9%94%AE%22%5D%0A%20%20X%20--%3E%20SMALL%5B%22%E5%8F%A6%E4%B8%80%E5%8D%8A%E7%BB%84%E5%90%8C%E7%90%86%E5%81%8F%E5%B0%8F%22%5D%0A%20%20SMALL%20--%3E%20DISC2%5B%22%E5%8F%A6%E4%B8%80%E4%BE%A7%E4%B9%9F%E8%87%B3%E5%B0%91%E7%BA%A6%203n%2F10%22%5D%0A%20%20DISC%20--%3E%20KEEP%5B%22%E9%80%92%E5%BD%92%E5%8F%AA%E8%B5%B0%20%E2%89%A4%207n%2F10%20%E7%9A%84%E4%B8%80%E4%BE%A7%22%5D%0A%20%20DISC2%20--%3E%20KEEP%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者容易以为「选好轴」就该写进产品代码。中位数的中位数保证的是最坏线性，但每层多做整轮分组，常数是随机分区的好几倍；工程默认仍用随机轴，确定性版本是理论保底。</span></p><p>后课 BFS 的「第 \\(k\\) 层」不是顺序统计量；对象换成图。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不优化 BFPRT 的常数，不处理同时多个顺序统计量。整数键上计数选择更快，那是<a href="/cs/radix-bucket">基数与桶</a>的模型，本课钉比较模型。后课默认：第 \\(k\\) 小最坏 \\(\\Theta(n)\\) 可及；数组算法收束，图从下一课起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五数取中保证轴两侧丢掉 \\(\\Theta(n)\\)，选择最坏线性。</li><li>递推 \\(T(n/5)+T(7n/10)+O(n)=\\Theta(n)\\)；常数大，实现仍可随机。</li><li>下界 \\(\\Omega(n)\\) 与上界同阶。</li><li>出处：Blum et al., 1973；CLRS 第 9.3 节。</li></ul>',6))])}const S=o(p,[["render",m]]);export{f as __pageData,S as default};
